sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoAnteriorSelecionadoAdj = null;
  $scope.dadosAnoAnteriorAdj = null;
  $scope.isFadingAnoAnteriorAdj = false;

  function carregarDadosAnoAnteriorAdj(anoFiltro) {
    $scope.isFadingAnoAnteriorAdj = true;

    if (anoFiltro) {
      var anoAnterior = parseInt(anoFiltro, 10) - 1;
      $scope.anoAnteriorSelecionadoAdj = anoAnterior;

      var params = { filtro_ano: anoAnterior };

      spUtil.get('rcl_ajustado_card_2', params).then(function(respAnoAnteriorAdj) {
        if (respAnoAnteriorAdj.data && respAnoAnteriorAdj.data.dadosAdjAnterior && respAnoAnteriorAdj.data.dadosAdjAnterior.length > 0) {
          $scope.dadosAnoAnteriorAdj = respAnoAnteriorAdj.data.dadosAdjAnterior[0];
        } else {
          $scope.dadosAnoAnteriorAdj = null;
        }
        $timeout(function() {
          $scope.isFadingAnoAnteriorAdj = false;
        }, 500);
      });

    } else {
      spUtil.get('rcl_ajustado_card_2').then(function(response) {
        var ultimoAno = null;

        if (response.data && response.data.dadosAdjAnterior && response.data.dadosAdjAnterior.length > 0) {
          ultimoAno = response.data.dadosAdjAnterior[0].anoAdjAnterior;
        }

        if (ultimoAno) {
          var anoAnterior = parseInt(ultimoAno, 10) - 1;
          $scope.anoAnteriorSelecionadoAdj = anoAnterior;

          var params = { filtro_ano: anoAnterior };

          spUtil.get('rcl_ajustado_card_2', params).then(function(respAnoAnteriorAdj) {
            if (respAnoAnteriorAdj.data && respAnoAnteriorAdj.data.dadosAdjAnterior && respAnoAnteriorAdj.data.dadosAdjAnterior.length > 0) {
              $scope.dadosAnoAnteriorAdj = respAnoAnteriorAdj.data.dadosAdjAnterior[0];
            } else {
              $scope.dadosAnoAnteriorAdj = null;
            }
            $timeout(function() {
              $scope.isFadingAnoAnteriorAdj = false;
            }, 300);
          });

        } else {
          $scope.dadosAnoAnteriorAdj = null;
          $scope.anoAnteriorSelecionadoAdj = null;
          $scope.isFadingAnoAnteriorAdj = false;
        }
      });
    }
  }

  carregarDadosAnoAnteriorAdj(null);

  $rootScope.$on('anoSelecionado', function(evt, anoSelecionado) {
    carregarDadosAnoAnteriorAdj(anoSelecionado);
  });
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

/* --- Wrapper Principal (Animação e Layout) --- */
.financial-widget-wrapper {
  font-family: 'Roboto Flex', sans-serif;
  margin-top: 4rem; /* Alinhamento padrão */

  /* Lógica de Transição */
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.financial-widget-wrapper.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

/* --- Estrutura Visual do Widget --- */
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
  font-family: 'Roboto Flex', sans-serif;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
  font-family: 'Roboto Flex', sans-serif;
}

/* Estilo para mensagem de "Nenhum dado" */
.indicator-value.small-text {
  font-size: 18px;
  color: #666;
  line-height: 1.5;
  padding: 20px;
}

/* --- Responsividade --- */
@media (max-width: 767px) {
  .financial-widget-wrapper {
    margin-top: 1rem;
  }
  .indicator-value {
    font-size: 24px;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .financial-widget-wrapper {
    margin-top: 2rem;
  }
}

@media (max-width: 350px) {
  .indicator-header {
    font-size: 12px;
  }
  .indicator-value {
    font-size: 20px;
    padding: 6px;
  }
}

sp_widget.script:
(function() {
  /*function formatarNumero(valor, divisor, sufixo) {
  var resultado = (valor / divisor);
  resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return resultado + ' ' + sufixo;
}R$ 26.850.804.430.339.996
*/
	function formatarNumero(valor) {
  if (typeof valor !== 'number') {
    valor = parseFloat(valor);
  }

  return valor.toFixed(2) // fixa duas casas decimais
              .replace('.', ',') // troca ponto decimal por vírgula
              .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // separador de milhar
}



  var anoFiltradoAdjAnterior = input && input.filtro_ano ? input.filtro_ano : null;

  if (!anoFiltradoAdjAnterior) {
    var grAnoAdjAnterior = new GlideRecord('x_sded9_portal_t_0_u_rreo');
    grAnoAdjAnterior.orderByDesc('u_ano');
    grAnoAdjAnterior.setLimit(1);
    grAnoAdjAnterior.query();

    if (!grAnoAdjAnterior.next()) {
      data.temDadoAdjAnterior = false;
      data.anoAdjAnterior = null;
      data.dadosAdjAnterior = [];
      return;
    }

    anoFiltradoAdjAnterior = grAnoAdjAnterior.getValue('u_ano');
  }

  var grSomaAdjAnterior = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  grSomaAdjAnterior.addQuery('u_ano', anoFiltradoAdjAnterior);
  grSomaAdjAnterior.query();

  var somaAdjAnterior = 0;
  while (grSomaAdjAnterior.next()) {
    somaAdjAnterior += parseFloat(grSomaAdjAnterior.getValue('adjusted_rreo_fiscal_management_report_2')) || 0;
  }

  if (somaAdjAnterior >= 0) {
   // var valorFormatadoAdjAnterior = (somaAdjAnterior >= 1000000000) ? formatarNumero(somaAdjAnterior, 1000000000, 'BI') 
   //   : formatarNumero(somaAdjAnterior, 1000000, 'MI');
		var valorFormatadoAdjAnterior = formatarNumero(somaAdjAnterior, 1, '');


    data.temDadoAdjAnterior = true;
    data.valorSomaAdjAnterior = somaAdjAnterior;
    data.valorSomaFormatadoAdjAnterior = valorFormatadoAdjAnterior;
    data.anoAdjAnterior = anoFiltradoAdjAnterior;
    data.dadosAdjAnterior = [{
      anoAdjAnterior: anoFiltradoAdjAnterior,
      valorSomaAdjAnterior: somaAdjAnterior,
      valorSomaFormatadoAdjAnterior: valorFormatadoAdjAnterior,
      temDadoAdjAnterior: true
    }];
  } else {
    data.temDadoAdjAnterior = false;
    data.anoAdjAnterior = anoFiltradoAdjAnterior;
    data.dadosAdjAnterior = [{
      anoAdjAnterior: anoFiltradoAdjAnterior,
      valorSomaAdjAnterior: 0,
      valorSomaFormatadoAdjAnterior: '0',
      temDadoAdjAnterior: false
    }];
  }
})();
